package com.bank.modes.launcher;

// The three Spark deployment modes, differing in WHERE the Driver runs.
public enum DeploymentMode {
    CLUSTER("worker node inside the cluster", true,  "scheduled production batch jobs"),
    CLIENT ("the submitting machine",         false, "interactive notebooks / spark-shell"),
    LOCAL  ("a single JVM (no cluster)",      false, "unit tests / debugging small data");

    private final String driverLocation;
    private final boolean survivesLauncherLoss;
    private final String bestFor;

    DeploymentMode(String driverLocation, boolean survivesLauncherLoss, String bestFor) {
        this.driverLocation = driverLocation;
        this.survivesLauncherLoss = survivesLauncherLoss;
        this.bestFor = bestFor;
    }
    public String driverLocation() { return driverLocation; }
    public boolean survivesLauncherLoss() { return survivesLauncherLoss; }
    public String bestFor() { return bestFor; }
}
