package com.bank.modes.launcher;

import com.bank.modes.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Describes and runs the same computation under a chosen deployment mode.
public class SparkLauncher {
    private static final Logger log = Logger.getLogger(SparkLauncher.class.getName());

    public Map<String, BigDecimal> run(DeploymentMode mode, List<Txn> txns) {
        log.info(() -> "Mode=" + mode
                + " | Driver runs on: " + mode.driverLocation()
                + " | survives launcher loss: " + mode.survivesLauncherLoss()
                + " | best for: " + mode.bestFor());

        if (mode == DeploymentMode.LOCAL) {
            log.fine("LOCAL: Driver + executors share one JVM using threads");
        } else if (mode == DeploymentMode.CLIENT) {
            log.warning("CLIENT: launcher machine is a single point of failure for this job");
        } else {
            log.info("CLUSTER: launcher may disconnect; job continues on the cluster");
        }

        // Same computation regardless of mode: total amount per account.
        Map<String, BigDecimal> totals = new HashMap<>();
        for (Txn t : txns) {
            totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        }
        return totals;
    }
}
