package com.bank.modes;

import com.bank.modes.launcher.DeploymentMode;
import com.bank.modes.launcher.SparkLauncher;
import com.bank.modes.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class ModesDemo {
    private static final Logger log = Logger.getLogger(ModesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new ModesLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Txn> txns = List.of(
            new Txn("SAV2001", new BigDecimal("1000")),
            new Txn("CUR3001", new BigDecimal("500")),
            new Txn("SAV2001", new BigDecimal("3000"))
        );

        SparkLauncher launcher = new SparkLauncher();
        for (DeploymentMode mode : DeploymentMode.values()) {
            var totals = launcher.run(mode, txns);
            log.info(() -> "  totals = " + totals);
        }
    }
}

